<?php if ($canWrite): ?><div class="management-grid"><details class="card form-card" <?= $error && ($_POST['action'] ?? '')==='subscription' ? 'open' : '' ?>><summary>+ Enregistrer un abonnement</summary><form method="post" action="subscription_quote" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="mode" value="create"><input type="hidden" name="phase" value="quote"><label>Membre actif *<select name="member_id" required><option value="">Sélectionner</option><?php foreach ($members as $m): ?><option value="<?= (int)$m['id'] ?>"><?= e($m['first_name'].' '.$m['last_name'].' · '.($m['card_number'] ?: 'Sans carte')) ?></option><?php endforeach; ?></select></label><label>Formule *<select name="plan" required><option value="">Sélectionner</option><?php foreach ($plans as $p): if (!$p['is_active']) continue; ?><option value="<?= (int)$p['id'] ?>|<?= e(PlanService::version($p)) ?>"><?= e($p['name'].' · '.(int)$p['duration_days'].' jours · '.dt($p['price'])) ?></option><?php endforeach; ?></select></label><label>Date de début *<input type="date" name="start" value="<?= date('Y-m-d') ?>" required></label><label>Promotion facultative<select name="promotion"><option value="">Aucune</option><?php foreach ($promotions as $promo): ?><option value="<?= (int)$promo['id'] ?>|<?= e(SubscriptionPricing::promotionVersion($promo)) ?>"><?= e($promo['code'].' · '.$promo['discount_percent'].' %') ?></option><?php endforeach; ?></select></label><p class="form-hint">La date de fin est calculée selon la durée. Le tarif et la réduction seront vérifiés avant confirmation. Les périodes actives ne doivent pas se chevaucher. Aucun paiement n’est créé automatiquement.</p><div class="form-actions"><button class="primary">Vérifier le prix</button></div></form></details><details class="card form-card"><summary>+ Créer une formule</summary><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="plan"><label>Nom *<input name="name" maxlength="100" required></label><label>Durée en jours *<input type="number" name="duration_days" min="1" max="3650" required></label><label>Prix (DT) *<input type="number" name="price" min="0" max="9999999" step="0.001" required></label><div class="form-actions"><button class="primary">Créer la formule</button></div></form></details></div><?php endif; ?>
<section class="card management-table"><div class="card-head"><div><h3>Abonnements</h3><p><?= $total ?> résultat(s)</p></div><?php if (in_array($_SESSION['user']['role'],['Admin','Gérant'],true)): ?><a class="text-link" href="subscription_prices">Vérifier les prix historiques</a><?php endif; ?></div><form action="subscriptions" method="get" class="search-form"><label class="sr-only" for="sub-query">Rechercher un abonnement</label><input id="sub-query" name="q" maxlength="120" placeholder="Membre, carte ou formule…" value="<?= e($q) ?>"><label for="sub-filter">Statut</label><select id="sub-filter" name="filter"><?php foreach ([''=>'Tous','current'=>'En cours','upcoming'=>'À venir','expired'=>'Expirés','frozen'=>'Gelés','cancelled'=>'Annulés'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $filter===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><button class="primary">Rechercher</button><?php if ($q || $filter): ?><a href="subscriptions">Effacer</a><?php endif; ?></form><div class="table-scroll"><table><thead><tr><th>MEMBRE</th><th>FORMULE</th><th>DÉBUT</th><th>FIN</th><th>PRIX FIXÉ</th><th>STATUT</th><th>ACTION</th></tr></thead><tbody><?php foreach ($subscriptions as $s): $display=$s['status']==='active' && $s['end_date']<date('Y-m-d') ? 'Expiré' : ($s['status']==='active' && $s['start_date']>date('Y-m-d') ? 'À venir' : ['active'=>'Actif','frozen'=>'Gelé','cancelled'=>'Annulé'][$s['status']]); ?><tr><td><strong><?= e($s['first_name'].' '.$s['last_name']) ?></strong></td><td><?= e($s['plan']) ?></td><td><?= e(date('d/m/Y',strtotime($s['start_date']))) ?></td><td><?= e(date('d/m/Y',strtotime($s['end_date']))) ?></td><td><?= $s['agreed_price']===null ? 'À vérifier' : e(dt($s['agreed_price'])) ?></td><td><span class="status <?= $display === 'Actif' ? '' : (in_array($display,['À venir','Gelé'],true) ? 'waiting-status' : 'expired') ?>"><?= e($display) ?></span></td><td><div class="subscription-actions"><a class="text-link" href="subscription_detail?id=<?= (int)$s['id'] ?>">Détails</a><?php if ($canWrite): ?><?php
$actions=[];
if ($s['status']==='active') {
    if ($s['start_date']<=date('Y-m-d') && $s['end_date']>=date('Y-m-d')) $actions['freeze']=['Geler','Geler cet abonnement à partir d’aujourd’hui ?'];
    $actions['cancel']=['Annuler','Annuler cet abonnement ? Aucun remboursement ne sera enregistré.'];
} elseif ($s['status']==='frozen') {
    $actions['resume']=['Réactiver','Réactiver cet abonnement et prolonger sa date de fin ?'];
    $actions['cancel']=['Annuler','Annuler cet abonnement gelé sans créditer les jours de gel ?'];
}
if ($s['status']==='active'): ?><a class="text-link" href="subscription_renew?id=<?= (int)$s['id'] ?>">Renouveler</a><?php endif;
foreach ($actions as $action=>[$label,$confirmation]): ?><form method="post" action="subscriptions"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="<?= e($action) ?>"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><button type="submit" class="link-button" data-confirm="<?= e($confirmation) ?>" onclick="return confirm(this.dataset.confirm)"><?= e($label) ?></button></form><?php endforeach; ?><?php endif; ?></div></td></tr><?php endforeach; ?><?php if (!$subscriptions): ?><tr><td colspan="7" class="empty">Aucun abonnement enregistré.</td></tr><?php endif; ?></tbody></table></div><div class="pagination"><?php if ($pageNumber>1): ?><a href="subscriptions?q=<?= urlencode($q) ?>&amp;filter=<?= urlencode($filter) ?>&amp;p=<?= $pageNumber-1 ?>">← Précédent</a><?php endif; ?><span>Page <?= $pageNumber ?> / <?= max(1,(int)ceil($total/10)) ?></span><?php if ($pageNumber*10<$total): ?><a href="subscriptions?q=<?= urlencode($q) ?>&amp;filter=<?= urlencode($filter) ?>&amp;p=<?= $pageNumber+1 ?>">Suivant →</a><?php endif; ?></div></section><section class="card management-table"><div class="card-head"><div><h3>Formules disponibles</h3><p>Durées et tarifs configurés</p></div></div><div class="table-scroll"><table><thead><tr><th>FORMULE</th><th>DURÉE</th><th>PRIX</th><th>STATUT</th><?php if ($canManagePlans): ?><th>ACTION</th><?php endif; ?></tr></thead><tbody><?php foreach ($plans as $p): ?><tr><td><?= e($p['name']) ?></td><td><?= (int)$p['duration_days'] ?> jours</td><td><?= e(dt($p['price'])) ?></td><td><?= $p['is_active'] ? 'Active' : 'Inactive' ?></td><?php if ($canManagePlans): ?><td><a class="text-link" href="plan?id=<?= (int)$p['id'] ?>">Gérer</a></td><?php endif; ?></tr><?php endforeach; ?><?php if (!$plans): ?><tr><td colspan="<?= $canManagePlans ? 5 : 4 ?>" class="empty">Aucune formule pour le moment.</td></tr><?php endif; ?></tbody></table></div></section>
